-- One-time data migration (2026-11-10): the reviewed University Preparation catalogue for production. No schema change.
--
-- Brings the site settings to the catalogue in packages/shared/src/university-packages.ts:
--   * universities: INHA, WIUT, MDIS, KIUT, Millat Umidi, CAU and TUIT get their official logos, descriptions, faculties and
--     directions; Narxoz is hidden (its record is kept, never deleted); TSUE and the medical and law preparation tracks are
--     added when missing;
--   * packages: the researched packages of the shown universities and tracks, each subject mapped to this tenant's offline
--     course by id, else by slug (a subject without such a course stays listed as not covered, never a made-up course).
--     A package is published by the rule of presetPublishability: an official source page, at least one covered required
--     subject, every named course available (published, public, with a group), no course twice, and its university shown.
--     Unverified requirements are published marked "requires confirmation" on the site. Prices are not stored.
--
-- Guarded: a university or package is replaced only while it is still exactly what 20261105 / 20261107 wrote (so nothing an
-- admin changed since is overwritten; such records are skipped and reported), added only when its id is missing, and never
-- removed. No other setting, user, subscription, payment, enrollment, course or group is touched.
-- Safety: the stored universities, packages and version are written to "AuditEvent" (action 'content.sync', id
-- 'catalog-update-20261110-SiteConfig') first; the update runs in its own sub-transaction, so a failure is rolled back and
-- reported without failing the migration. A database without the ILMORA catalog (tests, fresh installs) is left untouched,
-- and running it again changes nothing.
-- Undo: set "SiteConfig".data->'universities' and ->'presets' back to the "before" values of that audit row.

DO $sync$
DECLARE
  t text;
  uni_next jsonb := $unx$[{"id":"uni-inha","name":"Inha University in Tashkent","shortName":"INHA","city":"Tashkent","country":"Uzbekistan","website":"https://inha.uz","logoUrl":"/universities/uni-inha.svg","published":true,"description":{"uz":"Toşkentdagi Inha universiteti (IUT) 2014-yilda Koreya Respublikasidagi INHA universiteti bilan hamkorlikda taşkil etilgan. Bakalavriat dasturlari kompyuter va dasturiy injiniring hamda biznes va logistika yönalişlarini öz içiga oladi.","ru":"Университет Инха в Ташкенте (IUT) основан в 2014 году в сотрудничестве с Университетом INHA (Республика Корея). Бакалавриат включает направления компьютерной и программной инженерии, а также бизнеса и логистики.","en":"Inha University in Tashkent (IUT) was founded in 2014 in cooperation with INHA University in the Republic of Korea. Its undergraduate departments cover computer and software engineering, and business and logistics."},"faculties":[{"id":"inha-socie","name":{"uz":"Kompyuter va axborot injiniringi maktabi (SOCIE)","ru":"Школа компьютерной и информационной инженерии (SOCIE)","en":"School of Computer and Information Engineering (SOCIE)"},"directions":[{"id":"inha-socie-cse-ice","name":{"uz":"Kompyuter fanlari / Axborot va kommunikatsiya injiniringi (CSE, ICE)","ru":"Компьютерные науки / Информационно-коммуникационная инженерия (CSE, ICE)","en":"Computer Science / Information and Communication Engineering (CSE, ICE)"},"subjects":[{"uz":"Matematika","ru":"Математика","en":"Mathematics"},{"uz":"Fizika","ru":"Физика","en":"Physics"}]}]},{"id":"inha-sbl","name":{"uz":"Biznes va logistika maktabi (SBL)","ru":"Школа бизнеса и логистики (SBL)","en":"School of Business and Logistics (SBL)"},"directions":[{"id":"inha-sbl-ba","name":{"uz":"Biznes boşqaruvi (Business Administration)","ru":"Управление бизнесом (Business Administration)","en":"Business Administration"},"subjects":[{"uz":"Matematika","ru":"Математика","en":"Mathematics"}]},{"id":"inha-sbl-lm","name":{"uz":"Logistika menejmenti (Logistics Management)","ru":"Логистический менеджмент (Logistics Management)","en":"Logistics Management"},"subjects":[{"uz":"Matematika","ru":"Математика","en":"Mathematics"}]}]},{"id":"inha-uk","name":{"uz":"Buyuk Britaniya dasturlari","ru":"Британские программы","en":"UK programmes"},"directions":[{"id":"inha-uk-it","name":{"uz":"Axborot texnologiyalari","ru":"Информационные технологии","en":"Information Technology"},"subjects":[{"uz":"Matematika","ru":"Математика","en":"Mathematics"}]},{"id":"inha-uk-bm","name":{"uz":"Biznes va menejment","ru":"Бизнес и менеджмент","en":"Business and Management"},"subjects":[{"uz":"Matematika","ru":"Математика","en":"Mathematics"}]}]},{"id":"inha-italy","name":{"uz":"Italiya dasturi","ru":"Итальянская программа","en":"Italy programme"},"directions":[{"id":"inha-italy-ceds","name":{"uz":"Kompyuter injiniringi va ma’lumotlar fani","ru":"Компьютерная инженерия и наука о данных","en":"Computer Engineering and Data Science"},"subjects":[{"uz":"Matematika","ru":"Математика","en":"Mathematics"}]}]}]},{"id":"uni-narxoz","name":"Narxoz University","shortName":"Narxoz","city":"Almaty","country":"Kazakhstan","website":"https://narxoz.edu.kz","logoUrl":"/universities/uni-narxoz.png","description":{"uz":"Almatidagi Narxoz universiteti yetakçi Yevropa va Amerika universitetlari — Queen’s University Belfast, Mykolas Romeris University va Penn State University bilan qöş diplom dasturlarini amalga oşiradi. Ta’lim an’anaviy fakultetlar örniga fanlararo maktablar modeli asosida taşkil etilgan.","ru":"Университет Нархоз (Алматы) реализует программы двойного диплома с ведущими европейскими и американскими вузами — Queen's University Belfast, Mykolas Romeris University и Penn State University. Обучение организовано по междисциплинарной модели школ вместо традиционных факультетов.","en":"Narxoz University in Almaty runs dual-degree programmes with leading European and American universities: Queen's University Belfast, Mykolas Romeris University and Penn State University. Teaching is organised in interdisciplinary schools instead of traditional faculties."},"faculties":[{"id":"narxoz-bachelor","name":{"uz":"Bakalavriat: profil fanlar juftligi (tasdiqlanmagan)","ru":"Бакалавриат: пары профильных предметов (не подтверждено)","en":"Bachelor: profile-subject pairs (unverified)"},"directions":[{"id":"narxoz-math-informatics","name":{"uz":"Matematika + Informatika","ru":"Математика + Информатика","en":"Mathematics + Informatics"},"subjects":[{"uz":"Matematika","ru":"Математика","en":"Mathematics"},{"uz":"Informatika","ru":"Информатика","en":"Informatics"}]},{"id":"narxoz-math-geography","name":{"uz":"Matematika + Geografiya","ru":"Математика + География","en":"Mathematics + Geography"},"subjects":[{"uz":"Matematika","ru":"Математика","en":"Mathematics"},{"uz":"Geografiya","ru":"География","en":"Geography"}]},{"id":"narxoz-math-physics","name":{"uz":"Matematika + Fizika","ru":"Математика + Физика","en":"Mathematics + Physics"},"subjects":[{"uz":"Matematika","ru":"Математика","en":"Mathematics"},{"uz":"Fizika","ru":"Физика","en":"Physics"}]},{"id":"narxoz-english-geography","name":{"uz":"Ingliz tili + Geografiya","ru":"Английский язык + География","en":"English + Geography"},"subjects":[{"uz":"Ingliz tili","ru":"Английский язык","en":"English"},{"uz":"Geografiya","ru":"География","en":"Geography"}]},{"id":"narxoz-english-history","name":{"uz":"Ingliz tili + Jahon tarixi","ru":"Английский язык + Всемирная история","en":"English + World History"},"subjects":[{"uz":"Ingliz tili","ru":"Английский язык","en":"English"},{"uz":"Jahon tarixi","ru":"Всемирная история","en":"World History"}]},{"id":"narxoz-law-history","name":{"uz":"Huquq asoslari + Jahon tarixi","ru":"Основы права + Всемирная история","en":"Fundamentals of Law + World History"},"subjects":[{"uz":"Huquq asoslari","ru":"Основы права","en":"Fundamentals of Law"},{"uz":"Jahon tarixi","ru":"Всемирная история","en":"World History"}]}]}]},{"id":"uni-wiut","name":"Westminster International University in Tashkent","shortName":"WIUT","city":"Tashkent","country":"Uzbekistan","website":"https://wiut.uz","logoUrl":"/universities/uni-wiut-logo.png","published":true,"description":{"uz":"Toşkentdagi Westminster xalqaro universiteti (WIUT) 2002-yilda Londondagi Westminster universiteti, «Umid» Prezident jamğarmasi hamda Oliy va örta maxsus ta’lim vazirligi bilan birgalikda taşkil etilgan. Universitet Britaniyada akkreditatsiyadan ötgan darajalarni taklif etadi, barça dasturlar ingliz tilida öqitiladi.","ru":"Международный университет Вестминстер в Ташкенте (WIUT) основан в 2002 году совместно с Вестминстерским университетом (Лондон), Президентским фондом «Умид» и Министерством высшего и среднего специального образования. Университет предлагает степени с британской аккредитацией, все программы преподаются на английском языке.","en":"Westminster International University in Tashkent (WIUT) was established in 2002 in conjunction with the University of Westminster in London, the UMID Presidential Foundation and the Ministry of Higher and Secondary Specialized Education. It offers British-accredited degrees, and all programmes are taught in English."},"faculties":[{"id":"wiut-fsas","name":{"uz":"Faculty of Social and Applied Sciences (FSAS)","ru":"Faculty of Social and Applied Sciences (FSAS)","en":"Faculty of Social and Applied Sciences (FSAS)"},"directions":[{"id":"wiut-cs","name":{"uz":"BSc (Hons) in Computer Science","ru":"BSc (Hons) in Computer Science","en":"BSc (Hons) in Computer Science"},"subjects":[{"uz":"Matematika (Westminster tasdiqlagan matematika testi yoki unga teng)","ru":"Математика (тест, утверждённый University of Westminster, или эквивалент)","en":"Mathematics (maths test approved by the University of Westminster, or equivalent)"},{"uz":"Ingliz tili (IELTS 6.5 yoki unga teng)","ru":"Английский язык (IELTS 6.5 или эквивалент)","en":"English (IELTS 6.5 or equivalent)"}]},{"id":"wiut-bis","name":{"uz":"BSc (Hons) in Business Information Systems","ru":"BSc (Hons) in Business Information Systems","en":"BSc (Hons) in Business Information Systems"},"subjects":[]},{"id":"wiut-commercial-law","name":{"uz":"BA (Hons) in Commercial Law","ru":"BA (Hons) in Commercial Law","en":"BA (Hons) in Commercial Law"},"subjects":[{"uz":"Ingliz tili (IELTS 6.5 yoki unga teng)","ru":"Английский язык (IELTS 6.5 или эквивалент)","en":"English (IELTS 6.5 or equivalent)"}]},{"id":"wiut-ir-law","name":{"uz":"BA (Hons) in International Relations and Law","ru":"BA (Hons) in International Relations and Law","en":"BA (Hons) in International Relations and Law"},"subjects":[{"uz":"Ingliz tili (IELTS 6.5 yoki unga teng)","ru":"Английский язык (IELTS 6.5 или эквивалент)","en":"English (IELTS 6.5 or equivalent)"}]}]},{"id":"wiut-business-school","name":{"uz":"WIUT Business School","ru":"WIUT Business School","en":"WIUT Business School"},"directions":[{"id":"wiut-economics","name":{"uz":"BSc (Hons) in Economics (with Finance, with Data Science)","ru":"BSc (Hons) in Economics (with Finance, with Data Science)","en":"BSc (Hons) in Economics (with Finance, with Data Science)"},"subjects":[{"uz":"Matematika (Westminster tasdiqlagan matematika testi yoki unga teng)","ru":"Математика (тест, утверждённый University of Westminster, или эквивалент)","en":"Mathematics (maths test approved by the University of Westminster, or equivalent)"},{"uz":"Ingliz tili (IELTS 6.5 yoki unga teng)","ru":"Английский язык (IELTS 6.5 или эквивалент)","en":"English (IELTS 6.5 or equivalent)"}]},{"id":"wiut-finance","name":{"uz":"BSc (Hons) in Finance","ru":"BSc (Hons) in Finance","en":"BSc (Hons) in Finance"},"subjects":[{"uz":"Matematika (Westminster tasdiqlagan matematika testi yoki unga teng)","ru":"Математика (тест, утверждённый University of Westminster, или эквивалент)","en":"Mathematics (maths test approved by the University of Westminster, or equivalent)"},{"uz":"Ingliz tili (IELTS 6.5 yoki unga teng)","ru":"Английский язык (IELTS 6.5 или эквивалент)","en":"English (IELTS 6.5 or equivalent)"}]},{"id":"wiut-business-management","name":{"uz":"BA (Hons) in Business Management (with Finance, with Marketing)","ru":"BA (Hons) in Business Management (with Finance, with Marketing)","en":"BA (Hons) in Business Management (with Finance, with Marketing)"},"subjects":[{"uz":"Matematika (Westminster tasdiqlagan matematika testi yoki unga teng)","ru":"Математика (тест, утверждённый University of Westminster, или эквивалент)","en":"Mathematics (maths test approved by the University of Westminster, or equivalent)"},{"uz":"Ingliz tili (IELTS 6.5 yoki unga teng)","ru":"Английский язык (IELTS 6.5 или эквивалент)","en":"English (IELTS 6.5 or equivalent)"}]}]},{"id":"wiut-foundation-programme","name":{"uz":"International Foundation","ru":"International Foundation","en":"International Foundation"},"directions":[{"id":"wiut-foundation","name":{"uz":"Certificate in International Foundation Studies","ru":"Certificate in International Foundation Studies","en":"Certificate in International Foundation Studies"},"subjects":[{"uz":"Matematika (WIUT kiriş matematika imtihoni)","ru":"Математика (вступительный экзамен WIUT по математике)","en":"Mathematics (WIUT Mathematics Entrance Exam)"},{"uz":"Ingliz tili (IELTS 6.0 yoki unga teng)","ru":"Английский язык (IELTS 6.0 или эквивалент)","en":"English (IELTS 6.0 or equivalent)"}]}]}]},{"id":"uni-mdis","name":"Management Development Institute of Singapore in Tashkent","shortName":"MDIS","city":"Tashkent","country":"Uzbekistan","website":"https://mdis.uz","logoUrl":"/universities/uni-mdis.svg","published":true,"description":{"uz":"MDIS Tashkent 2007-yilda Özbekiston banklari assotsiatsiyasi va Management Development Institute of Singapore (MDIS) tomonidan MDISning birinçi xorijiy kampusi sifatida taşkil etilgan. Dasturlar Buyuk Britaniyadagi hamkorlar — Bangor universiteti va Sunderland universiteti, 2020-yildan esa Teesside universiteti bilan birgalikda olib boriladi.","ru":"MDIS Tashkent основан в 2007 году Ассоциацией банков Узбекистана и Management Development Institute of Singapore (MDIS) и стал первым зарубежным кампусом MDIS. Программы реализуются с британскими университетами-партнёрами — Бангорским университетом и Университетом Сандерленда, а с 2020 года также с Университетом Тиссайда.","en":"MDIS Tashkent was established in 2007 by the Uzbekistan Banking Association and the Management Development Institute of Singapore (MDIS), as MDIS's first overseas campus. Its programmes are delivered with UK partners Bangor University and the University of Sunderland, joined by Teesside University in 2020."},"faculties":[{"id":"mdis-foundation-year","name":{"uz":"Foundation Year","ru":"Foundation Year","en":"Foundation Year"},"directions":[{"id":"mdis-foundation","name":{"uz":"Foundation Year (route to the bachelor degrees)","ru":"Foundation Year (route to the bachelor degrees)","en":"Foundation Year (route to the bachelor degrees)"},"subjects":[{"uz":"Ingliz tili (IELTS yoki MDIS English Test 5.5+)","ru":"Английский язык (IELTS или MDIS English Test 5.5+)","en":"English (IELTS or MDIS English Test 5.5+)"}]}]},{"id":"mdis-sunderland","name":{"uz":"University of Sunderland (UK) bachelor programmes","ru":"University of Sunderland (UK) bachelor programmes","en":"University of Sunderland (UK) bachelor programmes"},"directions":[{"id":"mdis-sunderland-1","name":{"uz":"BA (Hons) Accounting and Finance","ru":"BA (Hons) Accounting and Finance","en":"BA (Hons) Accounting and Finance"},"subjects":[]},{"id":"mdis-sunderland-2","name":{"uz":"BA (Hons) Business and Financial Management","ru":"BA (Hons) Business and Financial Management","en":"BA (Hons) Business and Financial Management"},"subjects":[]},{"id":"mdis-sunderland-3","name":{"uz":"BA (Hons) Business and Management","ru":"BA (Hons) Business and Management","en":"BA (Hons) Business and Management"},"subjects":[]},{"id":"mdis-sunderland-4","name":{"uz":"BA (Hons) Business and Marketing Management","ru":"BA (Ho