gi tayyorgarligi","ru":"TUIT: подготовка — Программная инженерия, ИИ, кибербезопасность, компьютерная инженерия","en":"TUIT Software Engineering, AI, Cybersecurity, Computer Engineering Preparation"},"description":{"uz":"TUIT “Dasturiy injiniring, sun’iy intellekt, kiberxavfsizlik, kompyuter injiniringi” uçun rasmiy sahifada körsatilgan talablar böyiça tayyorgarlik. Kurslar — şu fanlar böyiça ILMORA oflayn kurslari; paket universitet bilan rasmiy boğliq emas.","ru":"Подготовка по требованиям, указанным на официальной странице TUIT для «Программная инженерия, ИИ, кибербезопасность, компьютерная инженерия». Курсы — офлайн-курсы ILMORA по этим предметам; пакет официально не связан с университетом.","en":"Preparation for the requirements TUIT states on its official page for Software Engineering, AI, Cybersecurity, Computer Engineering. The courses are ILMORA offline courses for these subjects; the package is not officially affiliated with the university."},"slots":[{"id":"uni-tuit-it-s1","label":{"uz":"Ona tili (özbek, rus yoki qoraqalpoq)","ru":"Родной язык (узбекский, русский или каракалпакский)","en":"Native language (Uzbek, Russian or Karakalpak)"},"courseId":null},{"id":"uni-tuit-it-s2","label":{"uz":"Matematika (majburiy fan va yönaliş fani)","ru":"Математика (обязательный и профильный предмет)","en":"Mathematics (mandatory and direction subject)"},"courseId":"c-algebra"},{"id":"uni-tuit-it-s3","label":{"uz":"Özbekiston tarixi","ru":"История Узбекистана","en":"History of Uzbekistan"},"courseId":null},{"id":"uni-tuit-it-s4","label":{"uz":"Fizika","ru":"Физика","en":"Physics"},"courseId":"c-physics"}],"admission":{"url":"https://admission.tuit.uz","academicYear":"","checkedOn":"2026-11-03","status":"needs_review","note":"To be verified: TUIT’s own sites (admission.tuit.uz, tuit.uz) announce 2026/2027 admission but list no faculties and no subjects per direction (the only direction list is for 2023/2024, and the directions page returns 404). Mathematics and Physics come from the State Testing Centre directory, which states no year."},"enabled":false},{"id":"uni-tuit-business","universityId":"uni-tuit","program":{"uz":"Iqtisodiyot, biznesni boşqariş, marketing, logistika","ru":"Экономика, управление бизнесом, маркетинг, логистика","en":"Economics, Business Management, Marketing, Logistics"},"directionIds":[],"name":{"uz":"TUIT Iqtisodiyot, biznesni boşqariş, marketing, logistika tayyorgarligi","ru":"TUIT: подготовка — Экономика, управление бизнесом, маркетинг, логистика","en":"TUIT Economics, Business Management, Marketing, Logistics Preparation"},"description":{"uz":"TUIT “Iqtisodiyot, biznesni boşqariş, marketing, logistika” uçun rasmiy sahifada körsatilgan talablar böyiça tayyorgarlik. Kurslar — şu fanlar böyiça ILMORA oflayn kurslari; paket universitet bilan rasmiy boğliq emas.","ru":"Подготовка по требованиям, указанным на официальной странице TUIT для «Экономика, управление бизнесом, маркетинг, логистика». Курсы — офлайн-курсы ILMORA по этим предметам; пакет официально не связан с университетом.","en":"Preparation for the requirements TUIT states on its official page for Economics, Business Management, Marketing, Logistics. The courses are ILMORA offline courses for these subjects; the package is not officially affiliated with the university."},"slots":[{"id":"uni-tuit-business-s1","label":{"uz":"Ona tili (özbek, rus yoki qoraqalpoq)","ru":"Родной язык (узбекский, русский или каракалпакский)","en":"Native language (Uzbek, Russian or Karakalpak)"},"courseId":null},{"id":"uni-tuit-business-s2","label":{"uz":"Matematika (majburiy fan va yönaliş fani)","ru":"Математика (обязательный и профильный предмет)","en":"Mathematics (mandatory and direction subject)"},"courseId":"c-algebra"},{"id":"uni-tuit-business-s3","label":{"uz":"Özbekiston tarixi","ru":"История Узбекистана","en":"History of Uzbekistan"},"courseId":null},{"id":"uni-tuit-business-s4","label":{"uz":"Çet tili (tili sahifada körsatilmagan)","ru":"Иностранный язык (язык на странице не указан)","en":"Foreign language (language not named on the page)"},"courseId":"c-general-english"}],"admission":{"url":"https://admission.tuit.uz","academicYear":"","checkedOn":"2026-11-03","status":"needs_review","note":"To be verified: TUIT’s own sites name no subjects for 2026/2027; Mathematics and a foreign language come from the State Testing Centre directory, which states no year."},"enabled":false}]$pko$::jsonb;
  unis jsonb;
  presets jsonb;
  u jsonb;
  uni jsonb;
  old jsonb;
  stored jsonb;
  pos integer;
  p jsonb;
  s jsonb;
  slots jsonb;
  dirs jsonb;
  cid text;
  blocking boolean;
  covered boolean;
  seen text[];
  preset jsonb;
  changed boolean := false;
  u_replaced text[] := ARRAY[]::text[];
  u_added text[] := ARRAY[]::text[];
  u_skipped text[] := ARRAY[]::text[];
  p_replaced integer := 0;
  p_added integer := 0;
  p_skipped text[] := ARRAY[]::text[];
  p_published integer := 0;
BEGIN
  SELECT "tenantId" INTO t FROM "Course" WHERE "id" = 'c-general-english' AND "deletedAt" IS NULL;
  IF t IS NULL THEN
    RAISE NOTICE 'catalog update: no ILMORA catalog in this database, nothing to do';
    RETURN;
  END IF;
  SELECT COALESCE("data"->'universities', '[]'::jsonb), COALESCE("data"->'presets', '[]'::jsonb) INTO unis, presets FROM "SiteConfig" WHERE "tenantId" = t;
  IF unis IS NULL OR jsonb_typeof(unis) <> 'array' OR jsonb_typeof(presets) <> 'array' THEN
    RAISE NOTICE 'catalog update: no site settings with universities and packages, nothing to do';
    RETURN;
  END IF;

  -- universities: replace what 20261105 wrote and nobody changed since; add what is missing; skip the rest
  FOR u IN SELECT x.v FROM jsonb_array_elements(uni_next) AS x(v) LOOP
    stored := NULL; pos := NULL; old := NULL;
    SELECT x.i - 1, x.v INTO pos, stored FROM jsonb_array_elements(unis) WITH ORDINALITY AS x(v, i) WHERE x.v->>'id' = u->>'id';
    SELECT x.v INTO old FROM jsonb_array_elements(uni_old) AS x(v) WHERE x.v->>'id' = u->>'id';
    IF stored IS NULL THEN
      unis := unis || jsonb_build_array(u); u_added := u_added || (u->>'id'); changed := true;
    ELSIF stored = u THEN
      NULL;
    ELSIF old IS NOT NULL AND stored = old THEN
      unis := jsonb_set(unis, ARRAY[pos::text], u); u_replaced := u_replaced || (u->>'id'); changed := true;
    ELSE
      u_skipped := u_skipped || (u->>'id');
    END IF;
  END LOOP;

  -- packages: built against this tenant's courses and the universities as they now are
  FOR p IN SELECT x.v FROM jsonb_array_elements(pkg_next) AS x(v) LOOP
    uni := NULL;
    SELECT x.v INTO uni FROM jsonb_array_elements(unis) AS x(v) WHERE x.v->>'id' = p->>'universityId';
    CONTINUE WHEN uni IS NULL;
    SELECT COALESCE(jsonb_agg(d.v), '[]'::jsonb) INTO dirs FROM jsonb_array_elements_text(p->'directionIds') AS d(v)
      WHERE EXISTS (
        SELECT 1 FROM jsonb_array_elements(COALESCE(uni->'faculties', '[]'::jsonb)) AS f(v), jsonb_array_elements(COALESCE(f.v->'directions', '[]'::jsonb)) AS dd(v)
        WHERE dd.v->>'id' = d.v);
    slots := '[]'::jsonb; blocking := false; covered := false; seen := ARRAY[]::text[];
    FOR s IN SELECT x.v FROM jsonb_array_elements(p->'slots') AS x(v) LOOP
      cid := NULL;
      IF s->>'courseKey' IS NOT NULL THEN
        SELECT c."id" INTO cid FROM "Course" c
          WHERE c."tenantId" = t AND c."deletedAt" IS NULL AND c."learningFormat" = 'OFFLINE'
            AND (c."id" = s->>'courseKey' OR c."slug" = regexp_replace(s->>'courseKey', '^c-', ''))
          ORDER BY (c."id" = s->>'courseKey') DESC LIMIT 1;
      END IF;
      IF cid IS NOT NULL THEN
        IF NOT EXISTS (
          SELECT 1 FROM "Course" c WHERE c."id" = cid AND c."status" = 'PUBLISHED' AND c."visibility" = 'PUBLIC'
            AND EXISTS (SELECT 1 FROM "Group" g WHERE g."courseId" = c."id" AND g."deletedAt" IS NULL)) THEN
          blocking := true;
        END IF;
        IF cid = ANY(seen) THEN blocking := true; END IF;
        seen := seen || cid;
        IF (s->>'optional')::boolean IS NOT TRUE THEN covered := true; END IF;
      END IF;
      slots := slots || jsonb_build_array(
        jsonb_build_object('id', s->'id', 'label', s->'label', 'courseId', cid)
        || CASE WHEN (s->>'optional')::boolean IS TRUE THEN '{"optional":true}'::jsonb ELSE '{}'::jsonb END);
    END LOOP;
    preset := jsonb_build_object(
      'id', p->'id', 'universityId', p->'universityId', 'program', p->'program', 'directionIds', dirs,
      'name', p->'name', 'description', p->'description', 'slots', slots, 'admission', p->'admission',
      'enabled', NOT blocking AND covered AND (p->>'hasSource')::boolean AND COALESCE((uni->>'published')::boolean, false));
    stored := NULL; pos := NULL; old := NULL;
    SELECT x.i - 1, x.v INTO pos, stored FROM jsonb_array_elements(presets) WITH ORDINALITY AS x(v, i) WHERE x.v->>'id' = p->>'id';
    SELECT x.v INTO old FROM jsonb_array_elements(pkg_old) AS x(v) WHERE x.v->>'id' = p->>'id';
    IF stored IS NULL THEN
      presets := presets || jsonb_build_array(preset); p_added := p_added + 1; changed := true;
    ELSIF stored = preset THEN
      NULL;
    ELSIF old IS NOT NULL AND stored = old THEN
      presets := jsonb_set(presets, ARRAY[pos::text], preset); p_replaced := p_replaced + 1; changed := true;
    ELSE
      p_skipped := p_skipped || (p->>'id');
      CONTINUE;
    END IF;
    IF (preset->>'enabled')::boolean THEN p_published := p_published + 1; END IF;
  END LOOP;

  IF NOT changed THEN
    RAISE NOTICE 'catalog update: nothing to change (skipped universities: %, skipped packages: %)', u_skipped, p_skipped;
    RETURN;
  END IF;
  IF jsonb_array_length(presets) > 150 OR jsonb_array_length(unis) > 100 THEN
    RAISE NOTICE 'catalog update: the lists would exceed the site settings limits, nothing changed';
    RETURN;
  END IF;

  BEGIN
    INSERT INTO "AuditEvent" ("id", "tenantId", "action", "entityType", "entityId", "before", "after", "reason")
    SELECT 'catalog-update-20261110-SiteConfig', t, 'content.sync', 'SiteConfig', t,
      jsonb_build_object('version', "version", 'universities', "data"->'universities', 'presets', "data"->'presets'),
      jsonb_build_object('universitiesReplaced', to_jsonb(u_replaced), 'universitiesAdded', to_jsonb(u_added), 'universitiesSkipped', to_jsonb(u_skipped),
        'packagesReplaced', p_replaced, 'packagesAdded', p_added, 'packagesSkipped', to_jsonb(p_skipped), 'packagesPublished', p_published),
      'University Preparation: reviewed catalogue (logos, faculties, TSUE, preparation tracks, packages)'
    FROM "SiteConfig" WHERE "tenantId" = t
    ON CONFLICT ("id") DO NOTHING;
    UPDATE "SiteConfig" SET "data" = jsonb_set(jsonb_set("data", '{universities}', unis), '{presets}', presets), "version" = "version" + 1, "updatedAt" = CURRENT_TIMESTAMP
      WHERE "tenantId" = t;
    RAISE NOTICE 'catalog update: universities replaced %, added %, skipped %; packages replaced %, added %, skipped %, published %',
      u_replaced, u_added, u_skipped, p_replaced, p_added, p_skipped, p_published;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'catalog update failed and was rolled back: %', SQLERRM;
  END;
END
$sync$;
